1import { useState, useMemo, useCallback } from "react";
2import Header from "./components/Header";
3import EntryCard from "./components/EntryCard";
4import Drawer from "./components/Drawer";
5import useFetch from "./hooks/useFetch";
6import useSearch from "./hooks/useSearch";
7import usePagination from "./hooks/usePagination";
8
9const ENTRIES_PER_PAGE = 5;
10
11function App() {
12  const { data, isLoading, error, refetch } = useFetch(
13    "https://api.programiz.pro/api/Demo/v1/journal-entries"
14  );
15  const [selectedEntry, setSelectedEntry] = useState(null);
16
17  const entries = useMemo(function () {
18    if (!data) return [];
19    return data.map(function (post) {
20      return {
21        ...post,
22        date: new Date(post.date).toLocaleDateString("en-US", {
23          year: "numeric", month: "short", day: "numeric"
24        }).toUpperCase()
25      };
26    });
27  }, [data]);
28
29  const { query, setQuery, filteredEntries } = useSearch(entries);
30  const { currentPage, pagedEntries, totalPages, handleNext, handlePrev, reset } = usePagination(
31    filteredEntries,
32    ENTRIES_PER_PAGE
33  );
34
35  const handleSelectEntry = useCallback(function (entry) {
36    setSelectedEntry(entry);
37  }, []);
38
39  const handleCloseDrawer = useCallback(function () {
40    setSelectedEntry(null);
41  }, []);
42
43  function handleQueryChange(newQuery) {
44    setQuery(newQuery);
45    reset();
46  }
47
48  return (
49    <div className="main-container">
50      <Header query={query} onQueryChange={handleQueryChange} />
51      <section className="entries-section">
52        <div className="entry-list-header">
53          <h3>Recent Entries</h3>
54          <span className="entry-count">{filteredEntries.length}</span>
55          {query && <span className="entry-count">{"of " + entries.length}</span>}
56          <button className="btn btn-secondary" onClick={refetch}>Refresh</button>
57        </div>
58        {isLoading ? (
59          <p className="loading-state">Loading entries...</p>
60        ) : error ? (
61          <div className="error-banner">
62            <p className="error-label">Something went wrong.</p>
63            <p className="error-detail">{error}</p>
64          </div>
65        ) : pagedEntries.length === 0 ? (
66          <p className="empty-state">No entries found.</p>
67        ) : (
68          pagedEntries.map((entry) => (
69            <EntryCard
70              key={entry.id}
71              id={entry.id}
72              title={entry.title}
73              date={entry.date}
74              content={entry.content}
75              author={entry.author}
76              onSelect={handleSelectEntry}
77            />
78          ))
79        )}
80        {!isLoading && !error && totalPages > 1 && (
81          <div className="pagination">
82            <button className="btn btn-secondary" onClick={handlePrev} disabled={currentPage === 1}>Previous</button>
83            <span className="pagination-info">Page {currentPage} of {totalPages}</span>
84            <button className="btn btn-secondary" onClick={handleNext} disabled={currentPage === totalPages}>Next</button>
85          </div>
86        )}
87      </section>
88      <Drawer entry={selectedEntry} onClose={handleCloseDrawer} />
89    </div>
90  );
91}
92
93export default App;

