3function useFetch(url) {
4  const [data, setData] = useState(null);
5  const [isLoading, setIsLoading] = useState(true);
6  const [error, setError] = useState(null);
7  const [refetchKey, setRefetchKey] = useState(0);
8
9  useEffect(function () {
10    async function fetchData() {
11      setIsLoading(true);
12      setError(null);
13      try {
14        const res = await fetch(url);
15        if (!res.ok) {
16          throw new Error("Could not load data. Status: " + res.status);
17        }
18        const json = await res.json();
19        setData(json);
20        setIsLoading(false);
21      } catch (err) {
22        setError(err.message);
23        setIsLoading(false);
24      }
25    }
26    fetchData();
27  }, [url, refetchKey]);
28
29  function refetch() {
30    setRefetchKey(function (k) { return k + 1; });
31  }
32
33  return { data, isLoading, error, refetch };
34}
35
36export default useFetch;

